  tools: GearTool[]
  slowest: GearSlow[]
  /** Calls started in each minute of the session, oldest first (at most 120). */
  perMinute: number[]
  startedAt: number
  mainCalls: number
  subCalls: number
  mainMs: number
  subMs: number
  inFlight: number
}

